xml.Script:
        Colors[ 0] := 'FFFFAA'; // LightYellow
        Colors[ 1] := '0077FF'; // LightBlue
        Colors[ 2] := 'BBBBBB'; // Gray
        Colors[ 3] := 'FF77EE'; // Pink
        Colors[ 4] := 'FF0000'; // Red
        Colors[ 5] := '009600'; // Green
        Colors[ 6] := 'FFFF00'; // Yellow
        Colors[ 7] := '00FF00'; // LightGreen
        Colors[ 8] := 'FF6600'; // Orange
        Colors[ 9] := '800080'; // Violett
        Colors[10] := 'FFFFFF'; // White
        Colors[11] := '0000FF'; // Blue

        R := 0.6;
        H := R*sqrt(2);

        WD := R * sqrt(2/27);
        for i := 0 to 3 do
            D[i] := (i - 1.5) * WD;

        N := 12;
        for i := 0 to N - 1 do begin
            x[i] := R * cos(2 * Pi / N * i);
            y[i] := R * sin(2 * Pi / N * i);
        end;

Macro.Script:
i1 := i mod N;
i2 := (i + 1) mod N;
Color := Colors[i];
Inc(i);

i1 := i mod N;
i2 := (i + 1) mod N;
Color := Colors[(i + N div 2) mod N];
Inc(i);
